import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./status-light.css";

export type LightState = "ok" | "warn" | "fail" | "running" | "idle";

export type StatusLightProps = Omit<ComponentProps<"div">, "children"> & {
  state: LightState;
  /** The word beside the lamps. Defaults to a plain name for the state; pass "" to show lamps only. */
  label?: string;
  orientation?: "vertical" | "horizontal";
};

const names: Record<LightState, string> = { ok: "Healthy", warn: "Degraded", fail: "Down", running: "Running", idle: "Idle" };
const lamps = ["fail", "warn", "ok"] as const;

/**
 * A three-lamp signal for a service or a build: red, amber, green. One lamp lights at a time and the others
 * stay dark; "running" breathes the amber lamp, "idle" lights none. Lamps come on quickly and fade out slowly,
 * the way a bulb does. The state is always written as text beside the lamps, so colour never carries it alone.
 * Under reduced motion the running lamp stays lit and lamps change without fading.
 */
export function StatusLight({ state, label, orientation = "vertical", className, ...props }: StatusLightProps) {
  const text = label ?? names[state];
  const lit = state === "running" ? "warn" : state === "idle" ? null : state;
  return (
    <div
      role="status"
      aria-label={text ? undefined : names[state]}
      data-slot="status-light"
      data-state={state}
      data-orientation={orientation}
      className={cn("inline-flex items-center gap-3", className)}
      {...props}
    >
      <span data-slot="stl-lamps" aria-hidden="true">
        {lamps.map((lamp) => (
          <i key={lamp} data-slot="stl-lamp" data-lamp={lamp} data-on={lamp === lit ? "" : undefined} />
        ))}
      </span>
      {text ? <span data-slot="stl-label">{text}</span> : null}
    </div>
  );
}

/* status-light.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Status light: three lamps, one lit; lamps come on quickly and fade slowly like a bulb. */
  [data-slot="status-light"] { color: var(--foreground); font-size: 14px; }
  [data-slot="status-light"] [data-slot="stl-lamps"] { display: inline-flex; flex-direction: column; gap: 5px; padding: 6px; border: 1px solid var(--border); border-radius: 12px; background: var(--muted); }
  [data-slot="status-light"][data-orientation="horizontal"] [data-slot="stl-lamps"] { flex-direction: row; }
  [data-slot="status-light"] [data-slot="stl-lamp"] { width: 14px; height: 14px; border-radius: 50%; background: var(--lamp); opacity: 0.18; transition: opacity 520ms var(--ease-out); }
  [data-slot="status-light"] [data-lamp="fail"] { --lamp: var(--destructive); }
  [data-slot="status-light"] [data-lamp="warn"] { --lamp: var(--warning); }
  [data-slot="status-light"] [data-lamp="ok"] { --lamp: var(--success); }
  [data-slot="status-light"] [data-slot="stl-lamp"][data-on] { opacity: 1; box-shadow: inset 1px 1px 0 color-mix(in oklab, white 38%, transparent); transition-duration: var(--duration-fast); }
  [data-slot="status-light"][data-state="running"] [data-slot="stl-lamp"][data-on] { animation: stl-breathe 1.6s var(--ease-in-out) infinite; }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="status-light"] [data-slot="stl-lamp"] { animation: none; }
  }
  @keyframes stl-breathe { 50% { opacity: 0.4; } }
}
